snippetModel.unrestricted:
if (filterContext.RequestContext.HttpContext.Request.AcceptTypes != null && filterContext.RequestContext.HttpContext.Request.AcceptTypes.Contains("application/json"))
            {
                // Handle JSON errors
                var exception = filterContext.Exception;
                var statusCode = (int)HttpStatusCode.InternalServerError;
                var statusText = HttpStatusCode.InternalServerError.ToString();

                if (exception is HttpException httpException)
                {
                    statusCode = httpException.GetHttpCode();
                }

                if(exception is EntityLockedException)
                {
                    statusCode = 423;
                    statusText = "Entity is locked";
                }

                if (exception is EntityDeletedException)
                {
                    statusCode = 410;
                    statusText = "Entity is deleted";
                }

                if (exception is EntityForbiddenException)
                {
                    statusCode = 403;
                    statusText = "Entity is forbidden";
                }

                var result = new JsonResult
                {
                    Data = new
                    {
                        status = statusCode,
                        statusText,
                        error = exception.Message,
                        stackTrace = exception.StackTrace
                    },
                    JsonRequestBehavior = JsonRequestBehavior.AllowGet
                };

                filterContext.Result = result;
                filterContext.HttpContext.Response.ContentType = "application/json";
                filterContext.HttpContext.Response.StatusCode = statusCode;
                filterContext.ExceptionHandled = true;
            }
            else
            {
                // Handle other errors (e.g., HTML)
                base.OnException(filterContext);
            }

