                    log.Messages.Add(new LogMessage(DateTime.Now, messages, username, "File upload", "upload"));
                    hookManager.Save(cache, log, "dataset", "details", HookMode.edit, id);
                }
            }
            else
            {
                return Json("No files selected.");
