                        if (user != null)
                        {
                            if (string.IsNullOrEmpty(user.Email))
                            {
                                ViewBag.ReturnUrl = returnUrl;
                                return View("Confirm", LdapLoginConfirmModel.Convert(user, model.Name));
                            }

